dslRule:
java.util.Vector<$E> $var = new java.util.Vector<$E>(); :: isLocalVariable($var)
=>
java.util.ArrayList<$E> $var = new java.util.ArrayList<$E>();
;;

beforeExample:
import java.util.Vector;

public class MyClass {
    public void processData(String input) {
        Vector<String> localData = new Vector<>();
        localData.add(input);
        System.out.println("Processed: " + localData.get(0));
    }

    private Vector<Integer> fieldVector = new Vector<>(); // This field should not be transformed

    public void anotherMethod() {
        Vector<Double> tempNumbers;
        tempNumbers = new Vector<>(); // This assignment should not be transformed
        tempNumbers.add(1.0);
    }
}

afterExample:
import java.util.ArrayList;
import java.util.Vector;

public class MyClass {
    public void processData(String input) {
        ArrayList<String> localData = new ArrayList<>();
        localData.add(input);
        System.out.println("Processed: " + localData.get(0));
    }

    private Vector<Integer> fieldVector = new Vector<>(); // This field should not be transformed

    public void anotherMethod() {
        Vector<Double> tempNumbers;
        tempNumbers = new Vector<>(); // This assignment should not be transformed
        tempNumbers.add(1.0);
    }
}

negativeExample:
import java.util.Vector;

public class MyClass {
    // This is a field declaration, should not be matched by the rule due to 'isLocalVariable($var)' guard
    private Vector<String> fieldVector = new Vector<>();

    public void someMethod() {
        // This is an assignment, not a declaration statement, so it should not be matched
        Vector<String> existingVector;
        existingVector = new Vector<>();
        existingVector.add("value");

        // Another method call, not a declaration
        callMethod(new Vector<>());
    }

    public void callMethod(Vector<String> vec) {
        System.out.println(vec);
    }
}
